def count_by_tag(notes):
    tag_counts = {}
    for note in notes:
        tags = note.get('tags', [])
        for tag in tags:
            if tag in tag_counts:
                tag_counts[tag] += 1
            else:
                tag_counts[tag] = 1
    return tag_counts

