        {'title': 'Note 1', 'tags': ['python', 'notes']},
        {'title': 'Note 2', 'tags': ['notes', 'tutorial']},
        {'title': 'Note 3', 'tags': ['python', 'coding']},
    ]
    print(count_by_tag(notes))

